Функция РассчитатьСумму(Номенклатура, Количество, Дата)
	// данные формы сюда не приезжают, работаем только с параметрами
	Запрос = Новый Запрос;
	Запрос.Текст =
		"ВЫБРАТЬ ПЕРВЫЕ 1
		|	Цены.Цена КАК Цена
		|ИЗ
		|	РегистрСведений.ЦеныНоменклатуры.СрезПоследних(&Дата, Номенклатура = &Номенклатура) КАК Цены";
	Запрос.УстановитьПараметр("Дата", Дата);
	Запрос.УстановитьПараметр("Номенклатура", Номенклатура);
	Выборка = Запрос.Выполнить().Выбрать();
	Цена = ?(Выборка.Следующий(), Выборка.Цена, 0);
	Возврат Количество * Цена;
КонецФункции

