&НаСервереБезКонтекста
Функция ЦеныПоНоменклатуре(Список)
    Запрос = Новый Запрос;
    Запрос.Текст =
    "ВЫБРАТЬ
    |    Цены.Номенклатура КАК Номенклатура,
    |    Цены.Цена КАК Цена
    |ИЗ
    |    РегистрСведений.ЦеныНоменклатуры.СрезПоследних(&Дата, Номенклатура В (&Список)) КАК Цены";
    Запрос.УстановитьПараметр("Дата", ТекущаяДатаСеанса());
    Запрос.УстановитьПараметр("Список", Список);

    // возвращаем Соответствие, а не ТаблицуЗначений:
    // ТЗ на тонкий и веб-клиент не передаётся
    Результат = Новый Соответствие;
    Выборка = Запрос.Выполнить().Выбрать();
    Пока Выборка.Следующий() Цикл
        Результат.Вставить(Выборка.Номенклатура, Выборка.Цена);
    КонецЦикла;
    Возврат Результат;
КонецФункции

