// ===== Модуль объекта документа =====

Процедура ПередЗаписью(Отказ, РежимЗаписи, РежимПроведения)

	Если ОбменДанными.Загрузка Тогда
		Возврат;
	КонецЕсли;

	// Черновик сохранить даём, запрещаем только проведение
	Если РежимЗаписи <> РежимЗаписиДокумента.Проведение Тогда
		Возврат;
	КонецЕсли;

	Если Не ЗначениеЗаполнено(СкладОтправитель) Тогда
		СообщитьОбОшибке("Не заполнен склад-отправитель", "СкладОтправитель", ЭтотОбъект);
		Отказ = Истина;
	КонецЕсли;

	Если Товары.Количество() = 0 Тогда
		СообщитьОбОшибке("Не заполнена табличная часть «Товары»", "Товары", ЭтотОбъект);
		Отказ = Истина;
	КонецЕсли;

	Для Каждого СтрокаТовара Из Товары Цикл
		Если Не ЗначениеЗаполнено(СтрокаТовара.Номенклатура) Тогда
			Путь = "Товары[" + Формат(СтрокаТовара.НомерСтроки - 1, "ЧН=0; ЧГ=0") + "].Номенклатура";
			СообщитьОбОшибке("Не заполнена номенклатура в строке " + СтрокаТовара.НомерСтроки, Путь, ЭтотОбъект);
			Отказ = Истина;
		КонецЕсли;
	КонецЦикла;

КонецПроцедуры

Процедура СообщитьОбОшибке(Текст, Поле, Данные)
	Сообщение = Новый СообщениеПользователю;
	Сообщение.Текст = Текст;
	// УстановитьДанные сам проставит КлючДанных и ПутьКДанным ("Объект"),
	// поэтому Поле пишем БЕЗ префикса "Объект." — иначе путь задвоится
	Сообщение.Поле  = Поле;
	Сообщение.УстановитьДанные(Данные);
	Сообщение.Сообщить();
КонецПроцедуры

// Условная проверка: убираем реквизит из стандартной проверки,
// чтобы не показать пользователю два сообщения об одном и том же
Процедура ОбработкаПроверкиЗаполнения(Отказ, ПроверяемыеРеквизиты)

	Если Не ТребуетсяДоговор() Тогда
		Индекс = ПроверяемыеРеквизиты.Найти("Договор");
		Если Индекс <> Неопределено Тогда
			ПроверяемыеРеквизиты.Удалить(Индекс);
		КонецЕсли;
	КонецЕсли;

КонецПроцедуры

