// формирование валютного движения в ОбработкеПроведения
// СчетРасчетов и СчетВалютный — счета с установленным признаком учёта «Валютный»
Движение = Движения.Хозрасчетный.Добавить();
Движение.Период      = Дата;
Движение.Организация = Организация;
Движение.СчетДт      = СчетРасчетов;
Движение.ВалютаДт    = Валюта;
Движение.ВалютнаяСуммаДт = СуммаВал;
Движение.СчетКт      = СчетВалютный;
Движение.ВалютаКт    = Валюта;
Движение.ВалютнаяСуммаКт = СуммаВал;
Движение.Сумма       = СуммаВал * Курс / Кратность; // рублёвая оценка

// получение курса
ВЫБРАТЬ
    Курсы.Курс КАК Курс,
    Курсы.Кратность КАК Кратность
ИЗ
    РегистрСведений.КурсыВалют.СрезПоследних(&Дата, Валюта = &Валюта) КАК Курсы

