Функция ОтправитьЗаказ(ДанныеЗаказа)

	Заголовки = Новый Соответствие;
	Заголовки.Вставить("Content-Type", "application/json");
	Заголовки.Вставить("Authorization", "Bearer " + ПолучитьТокен());

	Запись = Новый ЗаписьJSON;
	Запись.УстановитьСтроку();
	ЗаписатьJSON(Запись, ДанныеЗаказа);

	Запрос = Новый HTTPЗапрос("/api/v1/orders", Заголовки);
	Запрос.УстановитьТелоИзСтроки(Запись.Закрыть(),
		КодировкаТекста.UTF8,
		ИспользованиеByteOrderMark.НеИспользовать);

	Соединение = Новый HTTPСоединение("api.postavshik.ru", 443, , , ,
		30, Новый ЗащищенноеСоединениеOpenSSL());

	Попытка
		Ответ = Соединение.ОтправитьДляОбработки(Запрос);
	Исключение
		ЗаписьЖурналаРегистрации("Обмен.Заказы", УровеньЖурналаРегистрации.Ошибка,
			, , ПодробноеПредставлениеОшибки(ИнформацияОбОшибке()));
		Возврат Неопределено;
	КонецПопытки;

	Если Ответ.КодСостояния <> 200 И Ответ.КодСостояния <> 201 Тогда
		ЗаписьЖурналаРегистрации("Обмен.Заказы", УровеньЖурналаРегистрации.Ошибка,
			, , "HTTP " + Ответ.КодСостояния + ": " + Ответ.ПолучитьТелоКакСтроку());
		Возврат Неопределено;
	КонецЕсли;

	Чтение = Новый ЧтениеJSON;
	Чтение.УстановитьСтроку(Ответ.ПолучитьТелоКакСтроку());
	Возврат ПрочитатьJSON(Чтение, Истина);

