// (НомерСтроки заполняется при выгрузке табличной части: ТЧ.Выгрузить())
Функция РаспределитьПропорционально(Таблица, ОбщаяСумма) Экспорт

	Таблица.Сортировать("Сумма Убыв, НомерСтроки Возр");
	ИтогБазы = Таблица.Итог("Сумма");
	Если ИтогБазы = 0 Тогда
		Возврат Ложь;
	КонецЕсли;

	Распределено = 0;
	Последний = Таблица.Количество() - 1;
	Для Сч = 0 По Последний Цикл
		Строка = Таблица[Сч];
		Если Сч = Последний Тогда
			Строка.Добавка = ОбщаяСумма - Распределено;
		Иначе
			Строка.Добавка = Окр(ОбщаяСумма * Строка.Сумма / ИтогБазы, 2);
			Распределено = Распределено + Строка.Добавка;
		КонецЕсли;
	КонецЦикла;

	Возврат Таблица.Итог("Добавка") = ОбщаяСумма;

КонецФункции

