// Шаблон /v1/equipment, метод POST
Функция СоздатьОборудование(Запрос)

	Тело = РазобратьТелоКакСоответствие(Запрос);
	ВнешнийКлюч = Тело.Получить("externalId");
	Если НЕ ЗначениеЗаполнено(ВнешнийКлюч) Тогда
		Возврат ОтветОшибки(400, "INVALID_BODY", "Не передан externalId");
	КонецЕсли;

	// Быстрый путь: повтор без транзакции
	Ссылка = НайтиПоВнешнемуКлючу(ВнешнийКлюч);
	Если ЗначениеЗаполнено(Ссылка) Тогда
		Возврат ОтветУспеха(200, Ссылка);
	КонецЕсли;

	НачатьТранзакцию();
	Попытка

		Блокировка = Новый БлокировкаДанных;
		Элемент = Блокировка.Добавить("РегистрСведений.СоответствиеОборудованияВнешнейСистеме");
		Элемент.УстановитьЗначение("ВнешнийКлюч", ВнешнийКлюч);
		Блокировка.Заблокировать();

		// Повторная проверка уже под блокировкой
		Ссылка = НайтиПоВнешнемуКлючу(ВнешнийКлюч);
		Если ЗначениеЗаполнено(Ссылка) Тогда
			ЗафиксироватьТранзакцию();
			Возврат ОтветУспеха(200, Ссылка);
