Функция СравнитьВерсии(Версия1, Версия2) Экспорт

	Части1 = СтрРазделить(Версия1, ".", Ложь);
	Части2 = СтрРазделить(Версия2, ".", Ложь);

	Разрядов = ?(Части1.Количество() > Части2.Количество(), Части1.Количество(), Части2.Количество());

	Для Сч = 0 По Разрядов - 1 Цикл
		Разряд1 = ?(Сч < Части1.Количество(), Число(СокрЛП(Части1[Сч])), 0);
		Разряд2 = ?(Сч < Части2.Количество(), Число(СокрЛП(Части2[Сч])), 0);

		Если Разряд1 > Разряд2 Тогда
			Возврат 1;
		ИначеЕсли Разряд1 < Разряд2 Тогда
			Возврат -1;
		КонецЕсли;
	КонецЦикла;

	Возврат 0;

