Функция СлитьПоВозрастанию(Y, Z) Экспорт

	Результат = Новый Массив;
	ИндексY  = Y.Количество() - 1;
	ИндексZ  = Z.Количество() - 1;

	Для Шаг = 1 По Y.Количество() + Z.Количество() Цикл

		Если ИндексZ < 0 Тогда
			Результат.Добавить(Y[ИндексY]);
			ИндексY = ИндексY - 1;
		ИначеЕсли ИндексY < 0 Тогда
			Результат.Добавить(Z[ИндексZ]);
			ИндексZ = ИндексZ - 1;
		ИначеЕсли Y[ИндексY] <= Z[ИндексZ] Тогда
			Результат.Добавить(Y[ИндексY]);   // при равенстве берём из Y
			ИндексY = ИндексY - 1;
		Иначе
			Результат.Добавить(Z[ИндексZ]);
			ИндексZ = ИндексZ - 1;
		КонецЕсли;

	КонецЦикла;

	Возврат Результат;

