Функция Занято(Поле, НомерСтроки, НомерКолонки)
	Если НомерСтроки < 0 ИЛИ НомерСтроки > Поле.ВГраница() Тогда
		Возврат Ложь;
	КонецЕсли;
	СтрокаПоля = Поле[НомерСтроки];
	Если НомерКолонки < 0 ИЛИ НомерКолонки > СтрокаПоля.ВГраница() Тогда
		Возврат Ложь;
	КонецЕсли;
	Возврат СтрокаПоля[НомерКолонки] = 1;
КонецФункции

// Вариант для кораблей, которые НЕ соприкасаются: считаем начала.
Функция КоличествоКораблей(Поле) Экспорт

	Кораблей = 0;

	Для НомерСтроки = 0 По Поле.ВГраница() Цикл
		СтрокаПоля = Поле[НомерСтроки];
		Для НомерКолонки = 0 По СтрокаПоля.ВГраница() Цикл

			Если Не Занято(Поле, НомерСтроки, НомерКолонки) Тогда
				Продолжить;
			КонецЕсли;

			Если Не Занято(Поле, НомерСтроки, НомерКолонки - 1)
				И Не Занято(Поле, НомерСтроки - 1, НомерКолонки) Тогда
				Кораблей = Кораблей + 1;
			КонецЕсли;

		КонецЦикла;
	КонецЦикла;

	Возврат Кораблей;

