Функция ЭтоПалиндром(Знач Текст) Экспорт

	Текст = НРег(Текст);
	Длина = СтрДлина(Текст);

	Для Сч = 1 По Цел(Длина / 2) Цикл
		Если Сред(Текст, Сч, 1) <> Сред(Текст, Длина - Сч + 1, 1) Тогда
			Возврат Ложь;
		КонецЕсли;
	КонецЦикла;

	Возврат Истина;

