Процедура ОбработкаПроверкиЗаполнения(Отказ, ПроверяемыеРеквизиты)

	// склад проверяем сами, стандартную проверку по нему отключаем
	Индекс = ПроверяемыеРеквизиты.Найти("Склад");
	Если Индекс <> Неопределено Тогда
		ПроверяемыеРеквизиты.Удалить(Индекс);
	КонецЕсли;

	Если ЗначениеЗаполнено(Склад) Тогда
		Возврат;
	КонецЕсли;

	// один пакетный запрос вместо обхода ТЧ через точку
	Запрос = Новый Запрос;
	Запрос.Текст =
	"ВЫБРАТЬ
	|	Т.Номенклатура КАК Номенклатура
	|ПОМЕСТИТЬ ВТСтроки
	|ИЗ
	|	&Строки КАК Т
	|;
	|ВЫБРАТЬ ПЕРВЫЕ 1
	|	ВТСтроки.Номенклатура КАК Номенклатура
	|ИЗ
	|	ВТСтроки КАК ВТСтроки
	|		ВНУТРЕННЕЕ СОЕДИНЕНИЕ Справочник.Номенклатура КАК Ном
	|		ПО ВТСтроки.Номенклатура = Ном.Ссылка
	|ГДЕ
	|	Ном.ТипНоменклатуры = ЗНАЧЕНИЕ(Перечисление.ТипыНоменклатуры.Товар)";
	Запрос.УстановитьПараметр("Строки", Товары.Выгрузить("Номенклатура"));

	Если Запрос.Выполнить().Пустой() Тогда
		Возврат;
	КонецЕсли;

	СообщитьПользователю("Для товаров необходимо указать склад", , "Склад", , Отказ);

КонецПроцедуры

// Подписка на ПередЗаписью справочника: в транзакции только регистрируем факт.
// Перепроведение — отдельным регламентным заданием, пакетами, с ограничением по времени.
