	КонецЕсли;

	// в ПередЗаписью через ссылку читается ещё старое значение из БД
	СтароеЗначение = Источник.Ссылка.СтавкаНДС;
	Если СтароеЗначение = Источник.СтавкаНДС Тогда
		Возврат;
	КонецЕсли;

	Запись = РегистрыСведений.ОбъектыКПерепроведению.СоздатьМенеджерЗаписи();
	Запись.Объект = Источник.Ссылка;
	Запись.Момент = ТекущаяДатаСеанса();
	Запись.Записать();

