Процедура Печать(МассивОбъектов, КоллекцияПечатныхФорм, ОбъектыПечати, ПараметрыВывода) Экспорт

	ТабДок = Новый ТабличныйДокумент;
	Макет  = ПолучитьМакет("Макет");
	ОбластьШапка  = Макет.ПолучитьОбласть("Шапка");
	ОбластьСтрока = Макет.ПолучитьОбласть("СтрокаТаблицы");
	ОбластьПодвал = Макет.ПолучитьОбласть("Подвал");

	Запрос = Новый Запрос;
	Запрос.Текст =
	"ВЫБРАТЬ
	|	Товары.Ссылка КАК Ссылка,
	|	Товары.Ссылка.Номер КАК Номер,
	|	Товары.Ссылка.Дата КАК Дата,
	|	Товары.НомерСтроки КАК НомерСтроки,
	|	Товары.Номенклатура КАК Номенклатура,
	|	Товары.Количество КАК Количество,
	|	Товары.Цена КАК Цена,
	|	Товары.Сумма КАК Сумма
	|ИЗ
	|	Документ.РеализацияТоваровУслуг.Товары КАК Товары
	|ГДЕ
	|	Товары.Ссылка В (&МассивОбъектов)
	|
	|УПОРЯДОЧИТЬ ПО
	|	Ссылка,
	|	НомерСтроки
	|ИТОГИ
	|	СУММА(Сумма)
	|ПО
	|	Ссылка";
	Запрос.УстановитьПараметр("МассивОбъектов", МассивОбъектов);

	ВыборкаПоДокументу = Запрос.Выполнить().Выбрать(ОбходРезультатаЗапроса.ПоГруппировкам);
	ПредставлениеВида  = Метаданные.Документы.РеализацияТоваровУслуг.Синоним;

	Пока ВыборкаПоДокументу.Следующий() Цикл

		Если ТабДок.ВысотаТаблицы > 0 Тогда
			ТабДок.ВывестиГоризонтальныйРазделительСтраниц();
		КонецЕсли;
		НомерСтрокиНачало = ТабДок.ВысотаТаблицы + 1;

		ОбластьШапка.Параметры.ПредставлениеВида = ПредставлениеВида;
		ОбластьШапка.Параметры.Номер = ВыборкаПоДокументу.Номер;
		ОбластьШапка.Параметры.Дата  = ВыборкаПоДокументу.Дата;
		ТабДок.Вывести(ОбластьШапка);

		ВыборкаСтрок = ВыборкаПоДокументу.Выбрать();
		Пока ВыборкаСтрок.Следующий() Цикл
			ОбластьСтрока.Параметры.Заполнить(ВыборкаСтрок);
			ОбластьСтрока.Параметры.ЦенаТекст = ЦенаВФормате999(ВыборкаСтрок.Цена);
			ТабДок.Вывести(ОбластьСтрока);
		КонецЦикла;

		ОбластьПодвал.Параметры.ИтогоПрописью = ЧислоПрописью(
			ВыборкаПоДокументу.Сумма,
			"Л=ru_RU",
			"рубль, рубля, рублей, м, копейка, копейки, копеек, ж, 2");
		ТабДок.Вывести(ОбластьПодвал);

		УправлениеПечатью.ЗадатьОбластьПечатиДокумента(ТабДок, НомерСтрокиНачало,
			ОбъектыПечати, ВыборкаПоДокументу.Ссылка);

	КонецЦикла;

	УправлениеПечатью.ВывестиТабличныйДокументВКоллекцию(
		КоллекцияПечатныхФорм,
		"РеализацияЦены999",
		"Реализация (цены *9.99)",
		ТабДок);

КонецПроцедуры

// Правило согласовано с постановщиком: дробная часть заменяется на 0,99,
// целая уменьшается на единицу. Цены меньше рубля не трогаем.
Функция ЦенаВФормате999(Цена)

	Если Цена < 1 Тогда
		Возврат Формат(Цена, "ЧДЦ=2; ЧРД=.; ЧГ=0");
	КонецЕсли;

	Возврат Формат(Цел(Цена) - 1 + 0.99, "ЧДЦ=2; ЧРД=.; ЧГ=0");

КонецФункции

