// Модуль объекта документа РеализацияТоваровУслуг, расширение конфигурации

&После("ОбработкаЗаполнения")
Процедура Расш_ОбработкаЗаполнения(ДанныеЗаполнения, ТекстЗаполнения, СтандартнаяОбработка)

	Если ТипЗнч(ДанныеЗаполнения) <> Тип("ДокументСсылка.ЗаказКлиента") Тогда
		Возврат;
	КонецЕсли;

	ВидСвойства = Константы.ВидСвойстваНомерИнтернетЗаказа.Получить();
	Если Не ЗначениеЗаполнено(ВидСвойства) Тогда
		Возврат;
	КонецЕсли;

	Запрос = Новый Запрос;
	Запрос.Текст =
		"ВЫБРАТЬ ПЕРВЫЕ 1
		|	ДопРеквизиты.Значение КАК Значение
		|ИЗ
		|	Документ.ЗаказКлиента.ДополнительныеРеквизиты КАК ДопРеквизиты
		|ГДЕ
		|	ДопРеквизиты.Ссылка = &Основание
		|	И ДопРеквизиты.Свойство = &ВидСвойства";
	Запрос.УстановитьПараметр("Основание", ДанныеЗаполнения);
	Запрос.УстановитьПараметр("ВидСвойства", ВидСвойства);

	Выборка = Запрос.Выполнить().Выбрать();
	Если Не Выборка.Следующий() Тогда
		Возврат;
	КонецЕсли;

	СтрокаСвойства = ДополнительныеРеквизиты.Найти(ВидСвойства, "Свойство");
	Если СтрокаСвойства = Неопределено Тогда
		СтрокаСвойства = ДополнительныеРеквизиты.Добавить();
		СтрокаСвойства.Свойство = ВидСвойства;
	КонецЕсли;
	СтрокаСвойства.Значение = Выборка.Значение;

КонецПроцедуры

