&НаСервере
Процедура ЗагрузитьТоварыНаСервере(Адрес)
	ТаблицаПодбора = ПолучитьИзВременногоХранилища(Адрес);
	Для Каждого СтрокаПодбора Из ТаблицаПодбора Цикл
		СтрокаДокумента = Неопределено;
		Для Каждого Строка Из Объект.Товары Цикл
			Если Строка.Номенклатура = СтрокаПодбора.Номенклатура Тогда
				СтрокаДокумента = Строка;
				Прервать;
			КонецЕсли;
		КонецЦикла;
		Если СтрокаДокумента = Неопределено Тогда
			СтрокаДокумента = Объект.Товары.Добавить();
			СтрокаДокумента.Номенклатура = СтрокаПодбора.Номенклатура;
		КонецЕсли;
		СтрокаДокумента.Количество = СтрокаДокумента.Количество + СтрокаПодбора.Количество;
	КонецЦикла;
	Модифицированность = Истина;
КонецПроцедуры

// Модуль менеджера документа
Процедура ОбработкаПолученияФормы(ВидФормы, Параметры, ВыбраннаяФорма, ДополнительнаяИнформация, СтандартнаяОбработка)
	Если ВидФормы <> "ФормаОбъекта" Тогда
		Возврат;
	КонецЕсли;
	Если Не Параметры.Свойство("Ключ") Или Не ЗначениеЗаполнено(Параметры.Ключ) Тогда
		Возврат;
	КонецЕсли;

	Запрос = Новый Запрос(
		"ВЫБРАТЬ ВидОперации КАК ВидОперации
		|ИЗ Документ.Заявка
		|ГДЕ Ссылка = &Ссылка");
	Запрос.УстановитьПараметр("Ссылка", Параметры.Ключ);
	Выборка = Запрос.Выполнить().Выбрать();

	Если Выборка.Следующий() И Выборка.ВидОперации = Перечисления.ВидыОперацийЗаявки.Возврат Тогда
		ВыбраннаяФорма = "ФормаВозврата";
		СтандартнаяОбработка = Ложь;
	КонецЕсли;
КонецПроцедуры

