// Модуль объекта справочника Контрагенты
Процедура ПередЗаписью(Отказ)

	Если ОбменДанными.Загрузка ИЛИ Не ЗначениеЗаполнено(ИНН) Тогда
		Возврат;
	КонецЕсли;

	Ключ = СокрЛП(ИНН);

	Блокировка = Новый БлокировкаДанных;
	Элемент = Блокировка.Добавить("РегистрСведений.УникальныеИНН");
	Элемент.УстановитьЗначение("ИНН", Ключ);
	Блокировка.Заблокировать();

	Запрос = Новый Запрос;
	Запрос.Текст =
	"ВЫБРАТЬ ПЕРВЫЕ 1
	|	Ключи.Контрагент КАК Контрагент
	|ИЗ
	|	РегистрСведений.УникальныеИНН КАК Ключи
	|ГДЕ
	|	Ключи.ИНН = &ИНН
	|	И Ключи.Контрагент <> &ЭтотЭлемент";
	Запрос.УстановитьПараметр("ИНН", Ключ);
	Запрос.УстановитьПараметр("ЭтотЭлемент", Ссылка);

	Если Не Запрос.Выполнить().Пустой() Тогда
		Сообщение = Новый СообщениеПользователю;
		Сообщение.Текст = "Контрагент с таким ИНН уже есть в базе";
		Сообщение.Поле = "ИНН";
		Сообщение.КлючДанных = Ссылка;
		Сообщение.Сообщить();
		Отказ = Истина;
	КонецЕсли;

КонецПроцедуры

