// Обход иерархии с защитой от циклических ссылок
Процедура ОбойтиУзел(Узел, Посещенные, Результат)

	Если Посещенные.Получить(Узел) <> Неопределено Тогда
		Возврат; // циклическая ссылка в данных
	КонецЕсли;

	Посещенные.Вставить(Узел, Истина);
	Результат.Добавить(Узел);

	Для Каждого Дочерний Из ПодчиненныеУзлы(Узел) Цикл
		ОбойтиУзел(Дочерний, Посещенные, Результат);
	КонецЦикла;

КонецПроцедуры

