Функция ОстатокGET(Запрос) Экспорт
    Код = Запрос.ПараметрыURL["code"];
    Номенклатура = Справочники.Номенклатура.НайтиПоКоду(Код);
    Если Не ЗначениеЗаполнено(Номенклатура) Тогда
        Возврат ОтветJSON(404, Новый Структура("error", "not_found"));
    КонецЕсли;
    Возврат ОтветJSON(200, Новый Структура("code, qty", Код, ОстатокПоНоменклатуре(Номенклатура)));
КонецФункции

Функция ОтветJSON(КодСостояния, Данные)
    Запись = Новый ЗаписьJSON;
    Запись.УстановитьСтроку();
    ЗаписатьJSON(Запись, Данные);
    Тело = Запись.Закрыть();

    Ответ = Новый HTTPСервисОтвет(КодСостояния);
    Ответ.Заголовки.Вставить("Content-Type", "application/json; charset=utf-8");
    Ответ.УстановитьТелоИзСтроки(Тело, КодировкаТекста.UTF8, ИспользованиеByteOrderMark.НеИспользовать);
    Возврат Ответ;
