Процедура ОтсортироватьПузырьком(Массив)
    Для Проход = 1 По Массив.Количество() - 1 Цикл
        БылиОбмены = Ложь;
        Для Индекс = 0 По Массив.Количество() - 1 - Проход Цикл
            Если Массив[Индекс] > Массив[Индекс + 1] Тогда
                Буфер = Массив[Индекс];
                Массив[Индекс] = Массив[Индекс + 1];
                Массив[Индекс + 1] = Буфер;
                БылиОбмены = Истина;
            КонецЕсли;
        КонецЦикла;
        Если Не БылиОбмены Тогда
            Прервать;
        КонецЕсли;
    КонецЦикла;
КонецПроцедуры

Объект = Ссылка.ПолучитьОбъект();
Попытка
    Объект.Заблокировать();
    // второй параметр — ВключаяПодчиненные
    Объект.УстановитьПометкуУдаления(Истина, Истина);
Исключение
    Сообщение = Новый СообщениеПользователю;
    Сообщение.Текст = "Не удалось пометить на удаление: " + ОписаниеОшибки();
    Сообщение.Сообщить();
КонецПопытки;

Функция СоздатьПоступление(ДанныеШапки, ТаблицаТоваров) Экспорт

	Док = Документы.ПоступлениеТоваровУслуг.СоздатьДокумент();
	Док.Дата = ТекущаяДатаСеанса();
	ЗаполнитьЗначенияСвойств(Док, ДанныеШапки); // Организация, Контрагент, Договор, Склад

	Для Каждого СтрокаИсточника Из ТаблицаТоваров Цикл
		НоваяСтрока = Док.Товары.Добавить();
		ЗаполнитьЗначенияСвойств(НоваяСтрока, СтрокаИсточника);
	КонецЦикла;

	// Счета учёта константами не проставляем.
	// В БП 3.0 значения по умолчанию лежат в регистрах сведений
	// СчетаУчетаНоменклатуры и СчетаУчетаРасчетовСКонтрагентами;
	// вызываем штатную процедуру заполнения конфигурации — её имя
	// смотрим в модуле объекта документа конкретной конфигурации.

	Попытка
		Док.Записать(РежимЗаписиДокумента.Проведение);
	Исключение
		ЗаписьЖурналаРегистрации("Загрузка поступлений",
			УровеньЖурналаРегистрации.Ошибка, , ,
			ПодробноеПредставлениеОшибки(ИнформацияОбОшибке()));
		Возврат Неопределено;
	КонецПопытки;

	Если НЕ Док.Проведен Тогда
		ЗаписьЖурналаРегистрации("Загрузка поступлений",
			УровеньЖурналаРегистрации.Предупреждение, , Док.Ссылка, "Документ не проведён");
	КонецЕсли;

	Возврат Док.Ссылка;

КонецФункции

