Функция СоздатьПользователяВСервисе(Знач Имя, Знач Должность)

	Тело = Новый Структура("name, job", Имя, Должность);

	ЗаписьJSON = Новый ЗаписьJSON;
	ЗаписьJSON.УстановитьСтроку();
	ЗаписатьJSON(ЗаписьJSON, Тело);

	Заголовки = Новый Соответствие;
	Заголовки.Вставить("Content-Type", "application/json");
	Заголовки.Вставить("x-api-key", Константы.КлючAPI.Получить());

	Запрос = Новый HTTPЗапрос("/api/users", Заголовки);
	Запрос.УстановитьТелоИзСтроки(ЗаписьJSON.Закрыть(), КодировкаТекста.UTF8);

	Соединение = Новый HTTPСоединение("reqres.in", 443, , , , 30,
		Новый ЗащищенноеСоединениеOpenSSL);

	Ответ = Соединение.ВызватьHTTPМетод("POST", Запрос);

	Если Ответ.КодСостояния <> 201 Тогда
		ЗаписьЖурналаРегистрации("ОбменССервисом", УровеньЖурналаРегистрации.Ошибка, , ,
			"Код " + Ответ.КодСостояния + ": " + Ответ.ПолучитьТелоКакСтроку());
		Возврат "";
	КонецЕсли;

	Чтение = Новый ЧтениеJSON;
	Чтение.УстановитьСтроку(Ответ.ПолучитьТелоКакСтроку());
	ОтветJSON = ПрочитатьJSON(Чтение, Истина);

	Возврат Строка(ОтветJSON["id"]);

КонецФункции

Процедура ОбработкаПроведения(Отказ, РежимПроведения)

	Блокировка = Новый БлокировкаДанных;
	Элемент = Блокировка.Добавить("РегистрНакопления.ЗанятостьПарковки");
	Элемент.Режим = РежимБлокировкиДанных.Исключительный;
	Элемент.УстановитьЗначение("Здание", Здание);
	Блокировка.Заблокировать();

	Движения.ЗанятостьПарковки.Записывать = Истина;
	Для Каждого Строка Из ПарковочныеМеста Цикл
		Движение = Движения.ЗанятостьПарковки.Добавить();
		Движение.ВидДвижения = ВидДвиженияНакопления.Приход;
		Движение.Период     = Дата;
		Движение.Здание     = Здание;
		Движение.Контрагент = Контрагент;
		Движение.Количество = 1;
	КонецЦикла;
	Движения.ЗанятостьПарковки.Записать();

	Запрос = Новый Запрос;
	Запрос.Текст =
	"ВЫБРАТЬ
	|	Здания.КоличествоМест КАК Всего,
	|	ЕСТЬNULL(Остатки.КоличествоОстаток, 0) КАК Занято
	|ИЗ
	|	Справочник.Здания КАК Здания
	|		ЛЕВОЕ СОЕДИНЕНИЕ РегистрНакопления.ЗанятостьПарковки.Остатки(
	|				&МоментВремени, Здание = &Здание) КАК Остатки
	|		ПО Здания.Ссылка = Остатки.Здание
	|ГДЕ
	|	Здания.Ссылка = &Здание";
	Запрос.УстановитьПараметр("Здание", Здание);
	Запрос.УстановитьПараметр("МоментВремени",
		Новый Граница(МоментВремени(), ВидГраницы.Включая));

	Выборка = Запрос.Выполнить().Выбрать();
	Если Выборка.Следующий() И Выборка.Занято > Выборка.Всего Тогда
		Отказ = Истина;
		Сообщение = Новый СообщениеПользователю;
		Сообщение.Текст = "В здании " + Здание + " не хватает мест: занято "
			+ Выборка.Занято + " из " + Выборка.Всего;
		Сообщение.Сообщить();
	КонецЕсли;

КонецПроцедуры

