Процедура ПостроитьКолонки(Периоды)

	// 1. Убираем то, что добавляли в прошлый раз
	Удаляемые = Новый Массив;
	Для Каждого Реквизит Из ПолучитьРеквизиты("Данные") Цикл
		Если СтрНачинаетсяС(Реквизит.Имя, "Кол_") Тогда
			Удаляемые.Добавить("Данные." + Реквизит.Имя);
		КонецЕсли;
	КонецЦикла;

	// 2. Готовим новые реквизиты с безопасными именами
	Добавляемые = Новый Массив;
	Заголовки   = Новый Соответствие;
	Индекс = 0;
	Для Каждого Период Из Периоды Цикл
		Индекс = Индекс + 1;
		ИмяКолонки = "Кол_" + Индекс;
		Заголовок  = Формат(Период, "ДФ='MMMM yyyy'");
		Добавляемые.Добавить(Новый РеквизитФормы(ИмяКолонки,
			Новый ОписаниеТипов("Число"), "Данные", Заголовок));
		Заголовки.Вставить(ИмяКолонки, Заголовок);
	КонецЦикла;

	ИзменитьРеквизиты(Добавляемые, Удаляемые);

	// 3. Создаём элементы формы под каждую колонку
	Для Каждого КлючЗначение Из Заголовки Цикл
		Элемент = Элементы.Добавить(КлючЗначение.Ключ, Тип("ПолеФормы"), Элементы.Данные);
		Элемент.ПутьКДанным = "Данные." + КлючЗначение.Ключ;
		Элемент.Вид         = ВидПоляФормы.ПолеВвода;
		Элемент.Заголовок   = КлючЗначение.Значение;
	КонецЦикла;

КонецПроцедуры

